def parse_json(s: str) -> object:
    """
    Parses a JSON string into Python objects using a recursive approach.
    It handles strings (with escape sequences), numbers, booleans, null,
    arrays, and objects.
    """

    index = 0

    def parse_value():
        nonlocal index
        while index < len(s) and s[index].isspace():
            index += 1

        if index >= len(s):
            raise ValueError("Unexpected end of JSON string.")

        if s[index] == '"':
            return parse_string()
        elif s[index] == '{':
            return parse_object()
        elif s[index] == '[':
            return parse_array()
        elif s[index] in '-0123456789':
            return parse_number()
        elif s[index:index + 4] == 'true':
            index += 4
            return True
        elif s[index:index + 5] == 'false':
            index += 5
            return False
        elif s[index:index + 4] == 'null':
            index += 4
            return None
        else:
            raise ValueError(f"Invalid JSON value at index {index}")

    def parse_string():
        nonlocal index
        result = ''
        index += 1  # Skip the opening quote
        while index < len(s):
            char = s[index]
            if char == '"':
                index += 1  # Skip the closing quote
                return result
            elif char == '\\':
                index += 1
                if index < len(s):
                    escape_char = s[index]
                    if escape_char == 'n':
                        result += '\n'
                    elif escape_char == 't':
                        result += '\t'
                    elif escape_char in '"\\/':
                        result += escape_char
                    elif escape_char == 'b':
                        result += '\b'
                    elif escape_char == 'f':
                        result += '\f'
                    elif escape_char == 'r':
                        result += '\r'
                    elif escape_char == 'u':
                        # Parse Unicode escape
                        index += 1
                        hex_digits = s[index:index + 4]
                        result += chr(int(hex_digits, 16))
                        index += 3  # Skip the 4 hex digits
                    else:
                        raise ValueError(f"Invalid escape sequence at index {index}")
            else:
                result += char
            index += 1
        raise ValueError("Unterminated string")

    def parse_number():
        nonlocal index
        start_index = index
        if s[index] == '-':
            index += 1

        if s[index] == '0':
            index += 1
        else:
