            if index < len(s) and s[index].isdigit():
                while index < len(s) and s[index].isdigit():
                    index += 1
            else:
                raise ValueError("Invalid number format")

        number_str = s[start_index:index]
        if '.' in number_str or 'e' in number_str or 'E' in number_str:
            return float(number_str)
        else:
            return int(number_str)

    def parse_array():
        nonlocal index
        arr = []
        index += 1  # Skip the opening bracket
        while True:
            while index < len(s) and s[index].isspace():
                index += 1

            if index >= len(s):
                raise ValueError("Unexpected end of JSON array.")
            if s[index] == ']':
                index += 1  # Skip the closing bracket
                return arr

            arr.append(parse_value())

            while index < len(s) and s[index].isspace():
                index += 1

            if index < len(s) and s[index] == ',':
                index += 1  # Skip the comma
            elif index < len(s) and s[index] == ']':
                index += 1  # Skip the closing bracket
                return arr
            else:
                raise ValueError(f"Invalid array format at index {index}")

    def parse_object():
        nonlocal index
        obj = {}
        index += 1  # Skip the opening brace
        while True:
            while index < len(s) and s[index].isspace():
                index += 1

            if index >= len(s):
                raise ValueError("Unexpected end of JSON object.")
            if s[index] == '}':
                index += 1  # Skip the closing brace
                return obj

            key = parse_string()

            while index < len(s) and s[index].isspace():
                index += 1

            if index < len(s) and s[index] == ':':
                index += 1  # Skip the colon
            else:
                raise ValueError(f"Invalid object format at index {index}")

            value = parse_value()
            obj[key] = value

            while index < len(s) and s[index].isspace():
                index += 1

            if index < len(s) and s[index] == ',':
                index += 1  # Skip the comma
            elif index < len(s) and s[index] == '}':
                index += 1  # Skip the closing brace
                return obj
            else:
                raise ValueError(f"Invalid object format at index {index}")

    return parse_value()

