    """
    Parses a JSON string into Python objects using a state machine approach.
    This approach transitions between different states based on the current character
    and builds the resulting object incrementally.
    """

    index = 0

    def next_char():
        nonlocal index
        if index < len(s):
            char = s[index]
            index += 1
            return char
        return None

    def parse_value():
