        elif s[index-1:index+3] == 'true':
            index += 3
            return True
        elif s[index-1:index+4] == 'false':
            index += 4
            return False
        elif s[index-1:index+4] == 'null':
            index += 4
            return None
        else:
            raise ValueError(f"Unexpected character at index {index}")

