            elif char == '\\':
                escape_char = next_char()
                escape_sequences = {
                    '"': '"', '\\': '\\', '/': '/',
                    'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'
                }
                if escape_char in escape_sequences:
                    result.append(escape_sequences[escape_char])
                elif escape_char == 'u':
                    hex_chars = s[index:index + 4]
                    result.append(chr(int(hex_chars, 16)))
                    index += 4
                else:
                    raise ValueError(f"Invalid escape sequence at index {index}")
            else:
                if char is None:
                    raise ValueError("Unterminated string")
                result.append(char)

    def parse_number():
        start_index = index - 1
        while index < len(s) and (s[index].isdigit() or s[index] in '.eE+-'):
            next_char()
        number_str = s[start_index:index]
        if '.' in number_str or 'e' in number_str or 'E' in number_str:
            return float(number_str)
        return int(number_str)

    def parse_array():
        arr = []
        while True:
            char = next_char()
            if char == ']':
                return arr
            index -= 1  # backtrack to parse_value analysis
            arr.append(parse_value())
            char = next_char()
            if char == ']':
                return arr
            elif char != ',':
                raise ValueError(f"Invalid array syntax at index {index}")

    def parse_object():
        obj = {}
        while True:
            char = next_char()
            if char == '}':
                return obj
