def parse_json(s: str) -> object:
    """
    Parses a JSON string into Python objects using a stack-based approach.
    This technique uses a stack to manage nested structures (objects and arrays)
    and accommodates different data types by pushing and popping from the stack.
    """

    index = 0
    length = len(s)
    stack = []

    def next_char():
        nonlocal index
        if index < length:
            char = s[index]
            index += 1
            return char
        return None

    def parse_value():
        while index < length and s[index].isspace():
            next_char()
        char = next_char()

        if char == '"':
            stack.append(parse_string())
        elif char == '{':
            stack.append({})
            parse_object()
        elif char == '[':
            stack.append([])
            parse_array()
        elif char in '-0123456789':
            stack.append(parse_number(char))
        elif char == 't':
            stack.append(True)
            assert s[index:index + 3] == 'rue'
            index += 3
        elif char == 'f':
            stack.append(False)
            assert s[index:index + 4] == 'alse'
            index += 4
        elif char == 'n':
            stack.append(None)
            assert s[index:index + 3] == 'ull'
            index += 3
        else:
            raise ValueError(f"Unexpected character at index {index}")

    def parse_string():
        result = ''
