            char = next_char()
            if char == '"':
                return result
            elif char == '\\':
                char = next_char()
                escape_sequences = {
                    '"': '"', '\\': '\\', '/': '/',
                    'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'
                }
                if char == 'u':
                    hex_chars = s[index:index + 4]
                    result += chr(int(hex_chars, 16))
                    index += 4
                elif char in escape_sequences:
                    result += escape_sequences[char]
                else:
                    raise ValueError(f"Invalid escape character at index {index}")
            else:
                result += char

    def parse_number(initial_char):
        number_str = initial_char
        while index < length and (s[index].isdigit() or s[index] in '.eE+-'):
            number_str += next_char()
        if '.' in number_str or 'e' in number_str or 'E' in number_str:
            return float(number_str)
        return int(number_str)

    def parse_array():
        while True:
            while index < length and s[index].isspace():
                next_char()
            if s[index] == ']':
                next_char()  # Close array
                return
            parse_value()  # Add new value to array
            if s[index] == ',':
                next_char()  # Skip comma
            elif s[index] == ']':
                next_char()  # Close array
                return
            else:
                raise ValueError("Invalid array syntax at index {}".format(index))

    def parse_object():
        while True:
            while index < length and s[index].isspace():
                next_char()
            if s[index] == '}':
                next_char()  # Close object
                return
            key = parse_string()  # Parse key
            while index < length and s[index].isspace():
                next_char()
            if s[index] != ':':
                raise ValueError(f"Expected ':' after key at index {index}")
