            parse_value()  # Parse value
            if s[index] == ',':
                next_char()  # Skip comma
            elif s[index] == '}':
                next_char()  # Close object
                return
            else:
                raise ValueError(f"Invalid object syntax at index {index}")

    parse_value()
    return stack.pop()  # Final result is at the top of the stack
